#include "StdAfx.h"#include "QuickBuilder.h"//#include <SetData.h>int KQuickBuilder::InitL(){  OutputDebugString( "QuickBuilder::Init...\n" );  DWORD s = GetTickCount();  e_RestResult res = RestoreProject();  switch( res )  {  case err_DatVerGreaterSrcVer:    {      if( IDYES!=MessageBox( NULL, "Использовать текущую версию будете на свой страх и риск.\nПродолжить?"        , "Устаревшая версия QuickBuilder. Обновите QB.", MB_TOPMOST|MB_YESNO|MB_ICONWARNING|MB_DEFBUTTON2) )      {        exit( 1 );      }    }  case err_WrongKey:  case err_WrongVer:  case err_CantOpen:    if( ReadProject() )      return 2;    break;  default:  case err_CommonErr:    return 1;  case err_Ok:    break;  }  DWORD d = GetTickCount() - s;  char szDebug[64];  sprintf_s( szDebug, "время инициализации QuickBuilder %d ms (%d точек)\n", d, m_nPoints );  OutputDebugString( szDebug );  return 0;}int KQuickBuilder::Step0L(){  return 0;}int KQuickBuilder::Step1L(){  OutputDebugString( "KQuickBuilder::Step1 " );  OutputDebugString( m_szObjName );  OutputDebugString( " ...\n" );  DWORD s = GetTickCount();  if ( !m_bStep1 )  {    for( DWORD n=0; n<m_nPoints; ++n )    {      m_ppPoints[n]->Link();    }    m_bStep1 = true;  }  for( DWORD n=0; n<m_nPoints; ++n )  {    m_ppPoints[n]->AfterRestoreState();  }  DWORD d = GetTickCount() - s;  char szDebug[128];  sprintf_s( szDebug, "время связывания объетов QuickBuilder %d ms\n", d );  OutputDebugString( szDebug );  return 0;}/*int KQuickBuilder::SetData( int TypeData, void * pData ){  if( sd_SetRsuLinkCsv==TypeData )  {    m_bCreateData = true;  }  return 0;}*/